@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @ref="_textareaRef" @oninput="OnInput" rows="15" cols="80">@_content</textarea>

<div style="margin-top: 0.5rem;">
    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
    @if (_lastSavedAt is not null)
    {
        <span style="margin-left: 1rem;">Last saved at @_lastSavedAt</span>
    }
</div>

@code {
    private ElementReference _textareaRef;
    private NotepadInterop? _interop;
    private string _content = string.Empty;
    private string? _lastSavedAt;
    private bool _isDirty;
    private System.Threading.Timer? _autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            await _interop.InitializeAsync();

            var saved = await _interop.LoadAsync();
            if (!string.IsNullOrEmpty(saved))
            {
                _content = saved;
                StateHasChanged();
            }

            _autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSaveAsync),
                null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));
        }
    }

    private void OnInput(ChangeEventArgs e)
    {
        _content = e.Value?.ToString() ?? string.Empty;
        _isDirty = true;
    }

    private async Task AutoSaveAsync()
    {
        if (_isDirty)
        {
            await SaveAsync();
        }
    }

    private async Task SaveNowAsync()
    {
        await SaveAsync();
    }

    private async Task SaveAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(_content);
        _isDirty = false;
        _lastSavedAt = DateTime.Now.ToString("HH:mm:ss");
        StateHasChanged();
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;

        _content = string.Empty;
        _isDirty = false;
        _lastSavedAt = null;
        await _interop.ClearAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
        {
            await _autoSaveTimer.DisposeAsync();
        }

        if (_interop is not null)
        {
            await _interop.DisposeAsync();
        }
    }
}

const STORAGE_KEY = 'notepad-content';

let beforeUnloadHandler = null;

export function initialize() {
    beforeUnloadHandler = (e) => {
        e.preventDefault();
    };
}

export function enableBeforeUnload() {
    window.addEventListener('beforeunload', beforeUnloadHandler);
}

export function disableBeforeUnload() {
    window.removeEventListener('beforeunload', beforeUnloadHandler);
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY) || '';
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function dispose() {
    window.removeEventListener('beforeunload', beforeUnloadHandler);
}

using Microsoft.JSInterop;

namespace sv_6d9a3529286c42e8858a872ae422fec0.Components.Pages;

public sealed class NotepadInterop : IAsyncDisposable
{
    internal const string ModulePath = "./Components/Pages/Notepad.razor.js";
    internal const string InitMethod = "initialize";
    internal const string EnableBeforeUnloadMethod = "enableBeforeUnload";
    internal const string DisableBeforeUnloadMethod = "disableBeforeUnload";
    internal const string SaveMethod = "save";
    internal const string LoadMethod = "load";
    internal const string ClearMethod = "clear";
    internal const string DisposeMethod = "dispose";

    private readonly IJSRuntime _js;
    private IJSObjectReference? _module;

    public NotepadInterop(IJSRuntime js) => _js = js;

    private async ValueTask<IJSObjectReference> GetModuleAsync()
        => _module ??= await _js.InvokeAsync<IJSObjectReference>("import", ModulePath);

    public async ValueTask InitializeAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(InitMethod);
    }

    public async ValueTask SaveAsync(string content)
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(EnableBeforeUnloadMethod);
        await module.InvokeVoidAsync(SaveMethod, content);
        await module.InvokeVoidAsync(DisableBeforeUnloadMethod);
    }

    public async ValueTask<string> LoadAsync()
    {
        var module = await GetModuleAsync();
        return await module.InvokeAsync<string>(LoadMethod);
    }

    public async ValueTask ClearAsync()
    {
        var module = await GetModuleAsync();
        await module.InvokeVoidAsync(ClearMethod);
        await module.InvokeVoidAsync(DisableBeforeUnloadMethod);
    }

    public async ValueTask DisposeAsync()
    {
        try
        {
            if (_module is not null)
            {
                await _module.InvokeVoidAsync(DisposeMethod);
                await _module.DisposeAsync();
            }
        }
        catch (JSDisconnectedException) { }
    }
}

@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @ref="_textareaRef" @oninput="OnInput" rows="15" cols="80">@_content</textarea>

<div style="margin-top: 0.5rem;">
    <button @onclick="SaveNowAsync">Save now</button>
    <button @onclick="ClearAsync">Clear</button>
    @if (_lastSavedAt is not null)
    {
        <span style="margin-left: 1rem;">Last saved at @_lastSavedAt</span>
    }
</div>

@code {
    private ElementReference _textareaRef;
    private NotepadInterop? _interop;
    private string _content = string.Empty;
    private string? _lastSavedAt;
    private bool _isDirty;
    private System.Threading.Timer? _autoSaveTimer;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            await _interop.InitializeAsync();

            var saved = await _interop.LoadAsync();
            if (!string.IsNullOrEmpty(saved))
            {
                _content = saved;
                StateHasChanged();
            }

            _autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSaveAsync),
                null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));
        }
    }

    private void OnInput(ChangeEventArgs e)
    {
        _content = e.Value?.ToString() ?? string.Empty;
        _isDirty = true;
    }

    private async Task AutoSaveAsync()
    {
        if (_isDirty)
        {
            await SaveAsync();
        }
    }

    private async Task SaveNowAsync()
    {
        await SaveAsync();
    }

    private async Task SaveAsync()
    {
        if (_interop is null) return;

        await _interop.SaveAsync(_content);
        _isDirty = false;
        _lastSavedAt = DateTime.Now.ToString("HH:mm:ss");
        StateHasChanged();
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;

        _content = string.Empty;
        _isDirty = false;
        _lastSavedAt = null;
        await _interop.ClearAsync();
    }

    public async ValueTask DisposeAsync()
    {
        if (_autoSaveTimer is not null)
        {
            await _autoSaveTimer.DisposeAsync();
        }

        if (_interop is not null)
        {
            await _interop.DisposeAsync();
        }
    }
}

const STORAGE_KEY = 'notepad-content';

let beforeUnloadHandler = null;

export function initialize() {
    beforeUnloadHandler = (e) => {
        e.preventDefault();
    };
}

export function enableBeforeUnload() {
    window.addEventListener('beforeunload', beforeUnloadHandler);
}

export function disableBeforeUnload() {
    window.removeEventListener('beforeunload', beforeUnloadHandler);
}

export function save(content) {
    localStorage.setItem(STORAGE_KEY, content);
}

export function load() {
    return localStorage.getItem(STORAGE_KEY) || '';
}

export function clear() {
    localStorage.removeItem(STORAGE_KEY);
}

export function dispose() {
    window.removeEventListener('beforeunload', beforeUnloadHandler);
}

